use std::io::Write;
use std::sync::Mutex;

use log::{Level, LevelFilter, Log, Metadata, Record};

/// Simple logger that routes by level:
/// - info and above -> stdout (user-facing progress)
/// - debug/trace -> stderr (only when verbose at that level)
/// - warn/error -> stderr (always)
/// - log file captures all enabled levels
pub struct CliLogger {
    /// The verbose level for stderr output (None = no verbose)
    stderr_level: Option<LevelFilter>,
    log_file: Option<Mutex<std::fs::File>>,
}

impl CliLogger {
    pub fn new(stderr_level: Option<LevelFilter>, log_path: Option<&str>) -> Self {
        let log_file = log_path.map(|path| {
            Mutex::new(
                std::fs::OpenOptions::new()
                    .create(true)
                    .append(true)
                    .open(path)
                    .expect("failed to open log file"),
            )
        });
        CliLogger {
            stderr_level,
            log_file,
        }
    }

    /// Initialize as the global logger.
    /// `verbose`: 0 = off, 1 = debug, 2+ = trace
    pub fn init(verbose: u8, log_path: Option<&str>) {
        let stderr_level = match verbose {
            0 => None,
            1 => Some(LevelFilter::Debug),
            _ => Some(LevelFilter::Trace),
        };
        let has_log_file = log_path.is_some();
        let logger = Box::new(CliLogger::new(stderr_level, log_path));

        // Max level: stderr_level if set, otherwise info
        // Log file captures whatever is enabled, not more
        let _ = has_log_file;
        let max = stderr_level.unwrap_or(LevelFilter::Info); // OK: default verbosity when -v/-vv absent
        log::set_max_level(max);
        log::set_boxed_logger(logger).expect("failed to set logger");
    }
}

impl Log for CliLogger {
    fn enabled(&self, metadata: &Metadata) -> bool {
        // Always allow info and above
        if metadata.level() <= Level::Info {
            return true;
        }
        // Allow if stderr verbose is at this level
        if let Some(level) = self.stderr_level
            && metadata.level() <= level
        {
            return true;
        }
        false
    }

    fn log(&self, record: &Record) {
        if !self.enabled(record.metadata()) {
            return;
        }

        let msg = format!("{}", record.args());

        // Write to log file if configured: captures all levels
        if let Some(ref file) = self.log_file
            && let Ok(mut f) = file.lock()
        {
            let _ = writeln!(f, "[{:<5}] {}: {}", record.level(), record.target(), msg);
        }

        match record.level() {
            // User-facing progress -> stdout
            Level::Info => println!("{msg}"),
            // Errors and warnings -> stderr always
            Level::Error => eprintln!("error: {msg}"),
            Level::Warn => eprintln!("warn: {msg}"),
            // Debug/trace -> stderr only if verbose allows this level
            Level::Debug | Level::Trace => {
                if let Some(level) = self.stderr_level
                    && record.level() <= level
                {
                    for line in msg.lines() {
                        eprintln!("  {line}");
                    }
                }
            }
        }
    }

    fn flush(&self) {
        use std::io;
        let _ = io::stdout().flush();
        let _ = io::stderr().flush();
        if let Some(ref file) = self.log_file
            && let Ok(mut f) = file.lock()
        {
            let _ = f.flush();
        }
    }
}

//! `SubcommandRunner` trait
//!
//! The purpose is to simplify invoking a subcommand so `main`
//! can invoke any subcommand with one line:
//!
//! `Commands::Chid(args) => args.dispatch(&mut ctx),`
//!
//! Instead of the ~11 lines that the default `dispatch` below
//! now encapsulates.
//!
//! Implementors provide:
//!
//! - [`SubcommandRunner::to_params`]: build the clap-free
//!   `Params` from the clap `Args` (covers both `From` /
//!   `TryFrom` shapes uniformly via `Result<_, String>`).
//! - [`SubcommandRunner::run`]: the subcommand body.
//!
//! The default [`SubcommandRunner::dispatch`] builds `Params`
//! via `to_params`, runs via `run`, and maps the result to
//! `ExitCode`. Errors at any stage log via `error!` and return
//! `ExitCode::FAILURE`. `Context` is loaded once in `main` and
//! passed in by mutable reference (it owns the invocation's
//! lazily-opened repo sessions) so a single `Context` is shared
//! across the (one) match arm that actually runs.
//!
//! ## See also
//!
//! - The wider CLI-args / subcommand-layer split this trait
//!   formalizes: [`ARCHITECTURE.md > args -> Context + Params`][arch].
//! - Cycle design, ladder, evaluation gate:
//!   [`chores-10.md > 0.50.0-0`][open].
//! - Worked example, trait-shape decisions, naming:
//!   [`chores-10.md > 0.50.0-1`][port].
//! - First implementor: [`crate::chid`].
//!
//! [arch]: https://github.com/winksaville/vc-x1/blob/main/ARCHITECTURE.md#args--context--params
//! [open]: https://github.com/winksaville/vc-x1/blob/main/notes/chores/chores-10.md#chore-open-subcommand-trait-sweep-0500-0
//! [port]: https://github.com/winksaville/vc-x1/blob/main/notes/chores/chores-10.md#refactor-subcommandrunner-trait--chid-0500-1

use std::process::ExitCode;

use log::error;

use crate::context::Context;

/// Trait implemented by every subcommand's clap `Args` type so
/// `main.rs` can dispatch via a single `args.dispatch(&mut ctx)`
/// call.
pub trait SubcommandRunner {
    /// The clap-free `Params` struct the subcommand body
    /// consumes.
    type Params;

    /// Build `Params` from `Args`. `Result<_, String>` absorbs
    /// both `From` (return `Ok(...)`) and `TryFrom` (forward
    /// the error) shapes uniformly.
    fn to_params(&self) -> Result<Self::Params, String>;

    /// Run the subcommand body. `ctx` is mutable because it owns
    /// the invocation's lazily-opened repo sessions
    /// (`Context::session`).
    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>>;

    /// Default dispatch: build `Params` via `to_params`, bracket
    /// the run with `crate::bm_track` enter/exit, execute via
    /// `run`, and map the result to `ExitCode`. Errors at any
    /// stage log via `error!` and return `ExitCode::FAILURE`.
    /// `bm_track` itself emits at `debug!`, so default runs stay
    /// quiet: no per-call gate is needed here.
    fn dispatch(&self, ctx: &mut Context) -> ExitCode {
        let params = match self.to_params() {
            Ok(p) => p,
            Err(e) => {
                error!("{e}");
                return ExitCode::FAILURE;
            }
        };

        // Command name is the first positional after the binary;
        // clap has already validated it by the time we reach
        // dispatch (top-level parse errors exit earlier).
        let command_name = std::env::args().nth(1).unwrap_or_else(|| "?".to_string()); // OK: default when somehow invoked without a subcommand

        crate::bm_track("enter", &command_name);
        let exit_code = match Self::run(ctx, &params) {
            Ok(()) => ExitCode::SUCCESS,
            Err(e) => {
                error!("{e}");
                ExitCode::FAILURE
            }
        };
        crate::bm_track("exit ", &command_name);
        exit_code
    }
}

